/*
 * Flipbook clips for the right half: short one-bit films played at power-on,
 * at link and at idle, generated by tools/vid2clip.py.
 *
 * A clip is a list of frames in the display's own orientation (w wide, h
 * tall, at most 140x68; the right half's art area is 140x68, the left stage
 * 80x68). Each frame is run-length bytes: bit 7 is the pixel value, bits 0-6
 * the run length (1-127). Every frame after the first is XORed with the
 * previous one before packing, so a still background costs nothing. The
 * player keeps one 140x68 one-bit buffer and toggles the runs into it.
 *
 * Busy line art packs better as bytes (codec CLIP_BYTES): each frame is the
 * XOR delta in the buffer's own layout (rows of (w + 7) / 8 bytes, MSB first),
 * coded as headers: 0x00-0x7f is followed by header + 1 literal bytes to XOR
 * in, 0x80-0xff skips header - 0x7f unchanged bytes.
 *
 * SPDX-License-Identifier: MIT
 */

#pragma once

#include <lvgl.h>
#include <stdbool.h>
#include <stdint.h>

enum clip_codec {
    CLIP_BITS = 0,  /* bit runs, the default */
    CLIP_BYTES = 1, /* zero-run / literal bytes */
};

struct clip {
    uint16_t frames;
    uint8_t fps;
    uint8_t w; /* display orientation: w along the long side of the screen */
    uint8_t h;
    const uint8_t *data;
    const uint32_t *offsets; /* frames + 1 entries, byte offset of each frame in data */
    uint8_t codec;           /* enum clip_codec */
};

/* Play a clip on an lv_img object. done runs on the display thread after the
 * last frame, not when the clip is stopped. Playing a clip replaces the one in
 * progress. A NULL clip stops. */
void clip_play(lv_obj_t *img, const struct clip *clip, void (*done)(void));
void clip_stop(void);
bool clip_playing(void);
